SELECT , 
  FROM BOARD_MINUTES n 
 WHERE n.MINUTES_ID = #{id}

SELECT , FROM BOARD_MINUTES n
n.DELETED_YN = 0
AND ( (n.CREATED_BY = #{empNo} AND n.CREATED_AT >= #{uploaderSince}) OR EXISTS (SELECT 1 FROM BOARD_MINUTES_SCOPE s WHERE s.MINUTES_ID = n.MINUTES_ID AND s.GRANT_TYPE = 'EMP' AND s.GRANT_VALUE = #{empNo} AND s.GRANT_UNTIL >= #{today}) )
AND (n.TITLE LIKE CONCAT(CONCAT('%', #{q}), '%') ESCAPE '!' OR i.NAME_KO LIKE CONCAT(CONCAT('%', #{q}), '%') ESCAPE '!')
AND n.BOARD_YEAR = #{year}
AND n.MEETING_DATE >= #{meetingFrom}
AND n.MEETING_DATE <= #{meetingTo}
ORDER BY n.MEETING_DATE DESC, n.MINUTES_ID DESC

